SELECT e.id, e.course_id, e.user_id, e.status, e.applied_at, e.created_at,
       c.title AS course_title, c.course_code AS course_code,
       c.status AS course_status, i.name AS institution_name
  FROM tb_enrollments e
  JOIN tb_courses c ON c.id = e.course_id
  JOIN tb_institutions i ON i.id = c.institution_id
 WHERE e.user_id = #{userId}

   AND e.status = #{status}


LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_enrollments e
 WHERE e.user_id = #{userId}

   AND e.status = #{status}

SELECT e.id, e.course_id, e.user_id, e.status, e.applied_at, e.created_at,
       c.title AS course_title, u.name AS user_name
  FROM tb_enrollments e
  JOIN tb_courses c ON c.id = e.course_id
  JOIN tb_users u ON u.id = e.user_id
 WHERE c.institution_id = #{institutionId}

   AND e.status = #{status}


LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_enrollments e
  JOIN tb_courses c ON c.id = e.course_id
 WHERE c.institution_id = #{institutionId}

   AND e.status = #{status}

SELECT e.id AS enrollment_id, c.id AS course_id, c.title, i.name AS institution_name, AS learning_status, c.education_type, c.start_date, c.end_date, e.applied_at FROM tb_enrollments e JOIN tb_courses c ON c.id = e.course_id JOIN tb_institutions i ON i.id = c.institution_id WHERE e.user_id = #{userId} AND e.status IN ('APPLIED', 'WAITLISTED', 'APPROVED')
AND = #{learningStatus}
ORDER BY e.applied_at DESC, e.id ASC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_enrollments e
  JOIN tb_courses c ON c.id = e.course_id
 WHERE e.user_id = #{userId}
   AND e.status IN ('APPLIED', 'WAITLISTED', 'APPROVED')

   AND  = #{learningStatus}

SELECT 
  FROM tb_enrollments e
  JOIN tb_courses c ON c.id = e.course_id
  JOIN tb_users u ON u.id = e.user_id
  JOIN tb_course_instructors ci ON ci.course_id = c.id
 WHERE ci.user_id = #{instructorUserId}
   AND e.status = 'APPROVED'

   AND c.id = #{courseId}

ORDER BY c.title ASC, u.name ASC, e.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM tb_enrollments e
  JOIN tb_course_instructors ci ON ci.course_id = e.course_id
 WHERE ci.user_id = #{instructorUserId}
   AND e.status = 'APPROVED'

   AND e.course_id = #{courseId}
